sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiProperties = [
        'customwalk.properties'
    ];

    function fetchKPIs(propertyName) {
        var propertyValue = gs.getProperty(propertyName);

        if (!propertyValue) {
            gs.error("Property '" + propertyName + "' is empty or not set.");
            return null;
        }

        try {
            var categories = JSON.parse(propertyValue);
            var categoryArray = []; // Array to store category-based tasks

            categories.forEach(function(category) {
                // Create a category object
                var categoryObj = {
                    name: category.category,
                    actions: []
                };

                if (category.actions && Array.isArray(category.actions)) {
                    category.actions.forEach(function(action) {
                        if (action.description && action.short_description) {
                            var actionObj = {
                                type: action.type || "",
                                description: action.description.trim(),
                                short_description: action.short_description.trim(),
                                instruction: action.instruction || "",
                                value_builder_tasks: [] // Will hold related tasks
                            };

                            // Add any additional fields from the action
                            if (action.plugins) {
                                actionObj.plugins = action.plugins;
                            }

                            if (action.properties) {
                                actionObj.properties = action.properties;
                            }

                            categoryObj.actions.push(actionObj);
                        } else {
                            gs.error("Missing required fields in action: " + JSON.stringify(action));
                        }
                    });
                } else {
                    gs.error("No valid actions found in category: " + JSON.stringify(category));
                }

                // Only add categories with actions
                if (categoryObj.actions.length > 0) {
                    categoryArray.push(categoryObj);
                }
            });

            return categoryArray;
        } catch (e) {
            gs.error("Error parsing property '" + propertyName + "': " + e.message);
            return null;
        }
    }

    function fetchTasksFromValueBuilder(action) {
        var tasks = [];
        if (!action.description || !action.short_description) {
            gs.error("Missing description or short_description for action: " + JSON.stringify(action));
            return tasks;
        }

        var taskGR = new GlideRecord('samp_sp_vb_task');
        taskGR.addQuery('description', action.description);
        taskGR.addQuery('short_description', action.short_description);
        taskGR.addEncodedQuery('stateNOT IN2,-5,3,7'); // Exclude closed/canceled states
        taskGR.query();

        while (taskGR.next()) {
            tasks.push({
                sys_id: taskGR.getValue('sys_id'),
                number: taskGR.getValue('number'),
                description: taskGR.getValue('description'),
                short_description: taskGR.getValue('short_description'),
                state: taskGR.getValue('state')
            });
        }

        return tasks;
    }

    var result = {
        categories: []
    };

    for (var i = 0; i < kpiProperties.length; i++) {
        var categoryArray = fetchKPIs(kpiProperties[i]);

        if (categoryArray && categoryArray.length > 0) {
            // For each category, fetch the related tasks for each action
            categoryArray.forEach(function(category) {
                category.actions.forEach(function(action) {
                    action.value_builder_tasks = fetchTasksFromValueBuilder(action);
                });

                result.categories.push(category);
            });
        }
    }

    gs.info("Final CustomWalk Data: " + JSON.stringify(result));

    return result;
}
